CREATE TABLE IF NOT EXISTS "Organizations" (id serial PRIMARY KEY,"ownerId" integer NOT NULL UNIQUE REFERENCES "Users"(id) ON DELETE RESTRICT,name varchar(160) NOT NULL,currency varchar(3) NOT NULL CHECK(currency IN ('USD','CDF')),status varchar(20) NOT NULL DEFAULT 'ACTIVE',"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "Branches" (id serial PRIMARY KEY,"organizationId" integer NOT NULL REFERENCES "Organizations"(id),name varchar(160) NOT NULL,code varchar(32) NOT NULL,address varchar(250),active boolean NOT NULL DEFAULT true,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("organizationId",code));
CREATE TABLE IF NOT EXISTS "Warehouses" (id serial PRIMARY KEY,"organizationId" integer NOT NULL REFERENCES "Organizations"(id),"branchId" integer NOT NULL REFERENCES "Branches"(id),name varchar(160) NOT NULL,code varchar(32) NOT NULL,active boolean NOT NULL DEFAULT true,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("organizationId",code));
CREATE TABLE IF NOT EXISTS "Subscriptions" (id serial PRIMARY KEY,"organizationId" integer NOT NULL UNIQUE REFERENCES "Organizations"(id),plan varchar(32) NOT NULL,status varchar(24) NOT NULL,"startsAt" timestamptz NOT NULL,"endsAt" timestamptz,"branchLimit" integer NOT NULL CHECK("branchLimit">0),"warehouseLimit" integer NOT NULL CHECK("warehouseLimit">0),"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "SubscriptionEvents" (id serial PRIMARY KEY,"organizationId" integer NOT NULL REFERENCES "Organizations"(id),"actorId" integer NOT NULL,kind varchar(40) NOT NULL,reference varchar(100) NOT NULL,details jsonb NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("organizationId",reference));
CREATE UNIQUE INDEX IF NOT EXISTS branch_org_composite ON "Branches"("organizationId",id);
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='warehouse_branch_tenant_fk' AND conrelid='"Warehouses"'::regclass) THEN ALTER TABLE "Warehouses" ADD CONSTRAINT warehouse_branch_tenant_fk FOREIGN KEY ("organizationId","branchId") REFERENCES "Branches"("organizationId",id); END IF; END $$;
